<?php require 'includes/functions.php';
// One-time setup: no account can be created here after an admin exists.
$exists=query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();
if($_SERVER['REQUEST_METHOD']==='POST'&&!$exists){check_csrf();try{$email=field('email',190);$password=field('password',200);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new Exception('Use a valid email and a password of at least 8 characters.');
// A database advisory lock prevents simultaneous setup requests.
if(!query("SELECT GET_LOCK('mealbridge_setup',5)")->fetchColumn())throw new Exception('Setup is busy. Try again.');
try {if(query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn())throw new Exception('Setup is already complete.');query("INSERT INTO users(name,email,password,role,status,phone,city,address) VALUES(?,?,?,'admin','approved','0000000000','Manipal','MealBridge administration')",[field('name',100),$email,password_hash($password,PASSWORD_DEFAULT)]);}finally{query("SELECT RELEASE_LOCK('mealbridge_setup')");}
flash('Admin account created. Log in with the credentials you chose.');go('login.php');}catch(Exception $e){flash($e instanceof PDOException?'Could not create admin. Use an unregistered email.':$e->getMessage(),'error');go('setup.php');}}
$title='First-time setup';require 'includes/header.php';?><section class="section narrow"><div class="eyebrow">MEALBRIDGE SETUP</div><h1><?=$exists?'You’re all set.':'Set your table.'?></h1><?php if($exists):?><p>An admin account already exists. Setup is locked.</p><a class="button" href="<?=url('login.php')?>">Go to login</a><?php else:?><p>Create your first admin account. This page locks automatically after setup.</p><form class="panel" method="post"><?=csrf()?><?php input('Admin name','name','text','','maxlength="100"');input('Admin email','email','email','','maxlength="190"');input('Admin password','password','password','','minlength="8"');?><button class="button">Create admin account</button></form><?php endif;?></section><?php require 'includes/footer.php';?>